VERSAO_PRESENCIAL = 10
VERSAO_SEMIPRESENCIAL = 20
VERSAO_EAD = 30


def popular_versoes_modelos(apps, schema_editor):
    ModeloPAFC = apps.get_model('pafc', 'ModeloPAFC')
    Configuracao = apps.get_model('comum', 'Configuracao')

    config_modalidades_ead = Configuracao.objects.filter(app='pafc', chave='modalidades_totalmente_ead').first()
    config_modalidades_presenciais_com_ch_ead = Configuracao.objects.filter(app='pafc', chave='modalidades_presenciais_com_ch_ead').first()

    ids_modalidades_ead = [3] # padrão IFRN
    ids_modalidades_semipresenciais = [2] # padrão IFRN

    if config_modalidades_ead and config_modalidades_ead.valor is not None:
        ids_modalidades_ead = [int(_id) for _id in config_modalidades_ead.valor.split(',') if _id]
        if not ids_modalidades_ead:
            # reverte para valor padrão
            ids_modalidades_ead = [3]

    if config_modalidades_presenciais_com_ch_ead and config_modalidades_presenciais_com_ch_ead.valor is not None:
        ids_modalidades_semipresenciais = [int(_id) for _id in config_modalidades_presenciais_com_ch_ead.valor.split(',') if _id]
        if not ids_modalidades_semipresenciais:
            # reverte para valor padrão
            ids_modalidades_semipresenciais = [2]

    modelos = list(ModeloPAFC.objects.all())
    for modelo in tqdm(modelos):
        if modelo.modalidade_id in ids_modalidades_ead:
            modelo.versao_modelo = VERSAO_EAD
        elif modelo.modalidade_id in ids_modalidades_semipresenciais:
            modelo.versao_modelo = VERSAO_SEMIPRESENCIAL
        else:
            modelo.versao_modelo = VERSAO_PRESENCIAL

    ModeloPAFC.objects.bulk_update(modelos, ['versao_modelo'])


def remover_configuracoes_descontinuadas(apps, schema_editor):
    Configuracao = apps.get_model('comum', 'Configuracao')

    configs_descontinuadas = ['modalidades_totalmente_ead', 'modalidades_presenciais_com_ch_ead']
    Configuracao.objects.filter(app='pafc', chave__in=configs_descontinuadas).delete()


